  "An animated number with an editable target.":
    "Con số động với mục tiêu có thể chỉnh sửa.",
  "An animated price you can customize.": "Giá động có thể tùy chỉnh.",
  "An animated statistic with its explanation on a second line.":
    "Thống kê động với giải thích ở dòng thứ hai.",
  "An editable name or role label.": "Nhãn tên hoặc vai trò có thể chỉnh sửa.",
  "An editorial pull quote.": "Trích dẫn nổi bật theo phong cách biên tập.",
  "An estimate using the settings above. Duration, resolution, audio, and continuation change video costs. Manual editing and MP4 export use no AI credits.":
    "Ước tính theo cài đặt bên trên. Thời lượng, độ phân giải, âm thanh và chế độ nối tiếp thay đổi chi phí video. Chỉnh sửa thủ công và xuất MP4 không dùng tín dụng AI.",
