  "Chat preferences": "Tùy chọn trò chuyện",
  "Check OpenRouter key authentication and sound service settings. This check creates no media, spends no REELassati credits, and does not verify a generation.":
    "Kiểm tra xác thực khóa OpenRouter và cài đặt dịch vụ âm thanh. Việc này không tạo nội dung, không dùng tín dụng REELassati và không xác minh lần tạo nào.",
  "Check available credits and recent credit activity. The credit guide explains the actions you can run; paid generation shows its cost before it starts.":
    "Kiểm tra tín dụng hiện có và hoạt động gần đây. Hướng dẫn tín dụng giải thích tác vụ có thể chạy; tạo nội dung trả phí hiện chi phí trước khi bắt đầu.",
  "Check connection status": "Kiểm tra trạng thái kết nối",
  "Check connections": "Kiểm tra kết nối",
  "Check database, media storage, AI, and publishing availability. A configured service may still return a specific error for an individual request.":
    "Kiểm tra cơ sở dữ liệu, lưu trữ, AI và xuất bản có khả dụng không. Dịch vụ đã cấu hình vẫn có thể trả lỗi riêng cho từng yêu cầu.",
  "Check details, text, and composition in the result. Find recent images here or reuse the saved file from Library in an edit.":
    "Kiểm tra chi tiết, chữ và bố cục kết quả. Tìm ảnh gần đây tại đây hoặc dùng lại tệp đã lưu trong Thư viện để dựng.",
  "Check factual claims, identity, context, captions, timing, and the final media—not only the prompt or model response.":
    "Kiểm tra phát biểu thực tế, danh tính, ngữ cảnh, phụ đề, thời gian và nội dung cuối—không chỉ câu lệnh hay phản hồi của mô hình.",
  "Check provenance": "Kiểm tra nguồn gốc",
  "Check the available format, duration, and audio controls. Where a reference or continuity control is offered, use it to keep the next shot consistent.":
    "Kiểm tra điều khiển định dạng, thời lượng và âm thanh hiện có. Khi có tham chiếu hoặc điều khiển liên tục, dùng để giữ cảnh tiếp theo nhất quán.",
  "Check the displayed qualification rules and reward history. A signup and a verified reward are different stages.":
    "Kiểm tra quy tắc đủ điều kiện và lịch sử thưởng được hiển thị. Đăng ký và phần thưởng đã xác minh là các giai đoạn khác nhau.",
  "Check the evidence. Never guess the origin.":
    "Kiểm tra bằng chứng. Không đoán nguồn gốc.",
  "Check the services and workspace information behind the tools you use.":
    "Kiểm tra dịch vụ và thông tin không gian làm việc đứng sau công cụ bạn dùng.",
  "Check tool availability": "Kiểm tra công cụ khả dụng",
  "Check unavailable": "Không thể kiểm tra",
  "Check your email": "Kiểm tra email",
  "Check your inbox and spam folder. Open the reset link in the email to choose a new password.":
    "Kiểm tra hộp thư và thư rác. Mở liên kết đặt lại trong email để chọn mật khẩu mới.",
  "Check your inbox for the reset link.":
    "Kiểm tra hộp thư để lấy liên kết đặt lại.",
  "Check {{type}}": "Kiểm tra {{type}}",
  Checked: "Đã kiểm tra",
  "Checking connections…": "Đang kiểm tra kết nối…",
  "Children and changes": "Trẻ em và thay đổi",
  "Chinese (Mandarin)": "Tiếng Trung (Quan thoại)",
  "Choose a Library image": "Chọn ảnh Thư viện",
  "Choose a category relevant to the content you want to make.":
    "Chọn danh mục phù hợp với nội dung bạn muốn tạo.",
  "Choose a clear metric, target, and deadline. A concrete goal such as finishing four edits is easier to act on than “grow faster”.":
    "Chọn chỉ số, mục tiêu và hạn chót rõ. Mục tiêu cụ thể như hoàn thành bốn bản dựng dễ thực hiện hơn “tăng trưởng nhanh hơn”.",
  "Choose a finished asset, write the caption and hashtags, and review the platform preview. Complete the release questions shown for that content.":
    "Chọn tài nguyên hoàn chỉnh, viết chú thích và thẻ, rồi xem trước nền tảng. Hoàn tất các câu hỏi xuất bản được hiển thị cho nội dung đó.",
  "Choose a model to preview its pose.": "Chọn mô hình để xem trước tư thế.",
  "Choose a new password": "Chọn mật khẩu mới",
  "Choose a pattern below or write the opening logic yourself.":
    "Chọn cấu trúc bên dưới hoặc tự viết logic mở đầu.",
  "Choose a plan or top-up": "Chọn gói hoặc nạp thêm",
  "Choose a plan. If you are signed out, finish sign-in or signup with that plan selected, then review checkout before paying.":
    "Chọn gói. Nếu chưa đăng nhập, hoàn tất đăng nhập hoặc đăng ký với gói đó được chọn, rồi xem lại thanh toán trước khi trả tiền.",
  "Choose a platform and describe your niche, audience, or question. Narrow briefs return more relevant material than “what is viral?” alone.":
    "Chọn nền tảng và mô tả ngách, khán giả hoặc câu hỏi. Yêu cầu hẹp cho tư liệu phù hợp hơn chỉ hỏi “điều gì đang viral?”.",
  "Choose a preset, then edit its text, colors, timing and motion.":
    "Chọn mẫu rồi sửa chữ, màu, thời gian và chuyển động.",
  "Choose a relevant follow-up or write your own message. Keep the conversation focused on one issue for a clearer result.":
    "Chọn câu tiếp nối phù hợp hoặc viết tin nhắn riêng. Giữ cuộc trò chuyện tập trung một vấn đề để có kết quả rõ hơn.",
  "Choose a self-contained .glb file no larger than 25 MB.":
    "Chọn tệp .glb độc lập không lớn hơn 25 MB.",
  "Choose a specific action, such as finishing an edit or preparing a draft, then follow the relevant tool link.":
    "Chọn tác vụ cụ thể như hoàn thành bản dựng hoặc chuẩn bị nháp rồi theo liên kết công cụ phù hợp.",
  "Choose a starting style and adapt its brief to your project.":
    "Chọn phong cách khởi đầu và điều chỉnh yêu cầu theo dự án.",
  "Choose a subtitle file smaller than 2 MB.": "Chọn tệp phụ đề nhỏ hơn 2 MB.",
  "Choose a time, add a keyframe, then set its position, scale and rotation. The graphic moves between your keyframes.":
    "Chọn thời điểm, thêm khung hình khóa rồi đặt vị trí, tỷ lệ và góc xoay. Đồ họa di chuyển giữa các khung hình khóa.",
  "Choose a video file.": "Chọn tệp video.",
  "Choose a voice": "Chọn giọng",
  "Choose a voice by listening": "Chọn giọng bằng cách nghe",
  "Choose accent color": "Chọn màu nhấn",
  "Choose an audio file": "Chọn tệp âm thanh",
  "Choose an audio file first.": "Chọn tệp âm thanh trước.",
  "Choose an existing project below or start a new timeline with this":
    "Chọn dự án hiện có bên dưới hoặc bắt đầu dòng thời gian mới với nội dung này",
  "Choose an owned video, upload an original, or import a final video file. Import and measurement use no AI credits. Analysis is a separate action at the measured quote. Reference source timestamps are mapped to your own footage when planning edits.":
    "Chọn video bạn sở hữu, tải bản gốc hoặc nhập tệp video cuối. Nhập và đo không dùng tín dụng AI. Phân tích là tác vụ riêng với báo giá đã đo. Mốc thời gian nguồn tham chiếu được ánh xạ sang cảnh quay của bạn khi lập kế hoạch dựng.",
  "Choose file": "Chọn tệp",
