  "Continuity Lock reuses the selected clip, its scene direction, reference frames, and generation lineage. Write what happens next below. Consistency is strongly guided, not guaranteed pixel-for-pixel.":
    "Khóa Liên tục dùng lại clip đã chọn, định hướng cảnh, khung tham chiếu và dòng dõi tạo nội dung. Viết diễn biến tiếp theo bên dưới. Tính nhất quán được hướng dẫn mạnh nhưng không bảo đảm giống từng điểm ảnh.",
