  "I may download this reference and submit it to the AI analysis provider.":
    "Tôi được tải tham chiếu này và gửi tới nhà cung cấp phân tích AI.",
  "I may use the prompt, brands, references, faces and voices in this generation.":
    "Tôi được dùng câu lệnh, thương hiệu, tham chiếu, khuôn mặt và giọng trong lần tạo này.",
  "I may use this prompt, its brands, and its likenesses.":
    "Tôi được dùng câu lệnh này, thương hiệu và hình ảnh người trong đó.",
  "I may use this text and voice. If the voice identifies a real person, I have documented consent or another verified legal basis.":
    "Tôi được dùng văn bản và giọng này. Nếu giọng nhận diện người thật, tôi có đồng ý bằng văn bản hoặc cơ sở pháp lý khác đã xác minh.",
  "I need to open a support ticket": "Tôi cần mở phiếu hỗ trợ",
  "Idea — improvement request": "Ý tưởng — đề nghị cải thiện",
  Ideas: "Ý tưởng",
  "Identity and contact details for the REELassati service provider.":
    "Danh tính và liên hệ của nhà cung cấp dịch vụ REELassati.",
  "If a feature is not accessible, tell us the page, action, device, and assistive technology. We prioritise barriers affecting sign-in, purchase, creation, and account management: ":
    "Nếu không truy cập được tính năng, hãy cho biết trang, tác vụ, thiết bị và công nghệ hỗ trợ. Chúng tôi ưu tiên rào cản ở đăng nhập, mua hàng, tạo nội dung và quản lý tài khoản: ",
  "If a ticket is prepared, review its subject, description, and contact details before sending it. A prepared ticket is sent only after you submit it.":
    "Nếu chuẩn bị phiếu hỗ trợ, xem lại chủ đề, mô tả và liên hệ trước khi gửi. Phiếu đã chuẩn bị chỉ được gửi sau khi bạn nộp.",
  "If content appears to misuse your likeness, voice, work, or personal information, contact the human support channel with the relevant page, asset, or publication reference.":
    "Nếu nội dung có vẻ dùng sai hình ảnh, giọng, tác phẩm hoặc thông tin cá nhân của bạn, liên hệ hỗ trợ từ người cùng tham chiếu trang, tài nguyên hoặc bài đăng liên quan.",
  "If the page reports a failure, return to Sign in and try the same account method again. Include the error when contacting support.":
    "Nếu nhận lỗi trên trang, trở lại Đăng nhập và thử cùng cách đăng nhập tài khoản. Đính kèm lỗi khi liên hệ hỗ trợ.",
  "If you buy as a consumer in the EEA or a country with equivalent rights, a statutory withdrawal period may apply, commonly 14 days for distance contracts. If you request immediate service, you may owe a proportionate amount for service already supplied. Loss of withdrawal rights for digital content occurs only when all legal requirements, including express consent and acknowledgement, are met. To exercise a right, send an unambiguous statement with your account email and purchase to ":
    "Nếu mua với tư cách người tiêu dùng tại EEA hoặc nước có quyền tương đương, có thể có thời hạn rút lui theo luật, thường là 14 ngày cho hợp đồng từ xa. Nếu yêu cầu dịch vụ ngay, bạn có thể phải trả phần tương ứng dịch vụ đã cung cấp. Chỉ mất quyền rút lui với nội dung số khi đáp ứng mọi điều kiện pháp lý, gồm đồng ý và xác nhận rõ ràng. Để thực hiện quyền, gửi tuyên bố rõ cùng email tài khoản và giao dịch mua tới ",
  "If you received a code, enter it in the claim section and read the confirmation or eligibility message.":
    "Nếu nhận mã, nhập vào phần nhận mã và đọc xác nhận hoặc thông báo đủ điều kiện.",
  "If you used a social sign-in provider, use that provider’s access flow. Contact support if the account remains inaccessible.":
    "Nếu dùng nhà cung cấp đăng nhập xã hội, dùng luồng truy cập của họ. Liên hệ hỗ trợ nếu vẫn không vào được tài khoản.",
