  "One transparent REELassati balance for every AI tool. Plan credits refresh monthly; purchased top-ups roll over.":
    "Một số dư REELassati minh bạch cho mọi công cụ AI. Tín dụng gói làm mới tháng; phần nạp mua được cộng dồn.",
  "One truthful source of creative constraints for this workspace. Switch brands above to keep each client’s content separate.":
    "Một nguồn trung thực về ràng buộc sáng tạo cho không gian này. Đổi thương hiệu bên trên để tách nội dung từng khách hàng.",
  "Only confirmed paid-plan purchases count.":
    "Chỉ giao dịch mua gói trả phí đã xác nhận được tính.",
