  Opacity: "Độ đục",
  Open: "Mở",
  "Open Adjust": "Mở Điều chỉnh",
  "Open Graphics → Motion kits for a brand reveal, speaker introduction, chapter, quote, statistic or closing card. Edit the text, accent and duration; the brand reveal can use a logo from Library. Add at the playhead, then refine the grouped layers on the timeline. Undo removes the whole insertion. These native templates use no AI credits.":
    "Mở Đồ họa → Bộ chuyển động cho giới thiệu thương hiệu, người nói, chương, trích dẫn, thống kê hoặc thẻ kết. Sửa chữ, nhấn và thời lượng; giới thiệu thương hiệu có thể dùng logo Thư viện. Thêm tại đầu phát rồi tinh chỉnh lớp nhóm trên dòng thời gian. Hoàn tác gỡ toàn bộ. Mẫu gốc này không dùng tín dụng AI.",
