  "REELassati AI transcription": "Phiên âm AI REELassati",
  "REELassati AI-generated audio": "Âm thanh do AI REELassati tạo",
  "REELassati Support": "Hỗ trợ REELassati",
  "REELassati accessibility": "Khả năng tiếp cận REELassati",
  "REELassati combines manual production tools with reviewable AI assistance. This page identifies where AI is used, the information sent when you invoke it, and the controls that remain with you.":
    "REELassati kết hợp công cụ sản xuất thủ công với hỗ trợ AI có thể xem xét. Trang này nêu nơi AI được dùng, thông tin gửi khi bạn kích hoạt và kiểm soát bạn giữ.",
  "REELassati credits": "Tín dụng REELassati",
  "REELassati designs interfaces around WCAG 2.2 AA principles: semantic structure, accessible names, visible focus, contrast, keyboard navigation, reduced motion, and feedback that does not rely on colour alone. This is an operating target, not a claim of complete certified conformance.":
    "REELassati thiết kế giao diện theo nguyên tắc WCAG 2.2 AA: cấu trúc ngữ nghĩa, tên dễ tiếp cận, tiêu điểm rõ, tương phản, điều hướng bàn phím, giảm chuyển động và phản hồi không chỉ dựa màu. Đây là mục tiêu vận hành, không tuyên bố phù hợp được chứng nhận hoàn toàn.",
  "REELassati home": "Trang chủ REELassati",
  "REELassati is intended for human-directed creative and marketing production. It is not designed to make consequential decisions about people, infer sensitive traits, or present deceptive synthetic media as authentic.":
    "REELassati dành cho sản xuất sáng tạo và tiếp thị do người định hướng. Không được thiết kế để quyết định hệ trọng về người, suy ra đặc điểm nhạy cảm hoặc trình bày nội dung tổng hợp lừa dối là thật.",
  "REELassati is intended for users aged 18 or older. Material changes to this notice will be communicated appropriately before they take effect.":
    "REELassati dành cho người từ 18 tuổi. Thay đổi quan trọng của thông báo được truyền đạt phù hợp trước khi có hiệu lực.",
  "REELassati provides tools to plan, create, edit, analyse, organise, and publish short-form content. You must be at least 18 and able to enter a contract. Anyone using the service for an organisation confirms authority to bind it.":
    "REELassati cung cấp công cụ lập kế hoạch, tạo, dựng, phân tích, tổ chức và xuất bản nội dung ngắn. Bạn phải từ 18 tuổi và có khả năng giao kết hợp đồng. Ai dùng cho tổ chức xác nhận thẩm quyền ràng buộc tổ chức.",
  "REELassati updates this feed internally; no action or credits are required from you.":
    "REELassati cập nhật bảng tin nội bộ; bạn không cần hành động hay tín dụng.",
