  "Review and export my edit": "Xem và xuất bản dựng của tôi",
  "Review and reuse": "Xem và dùng lại",
  "Review available performance evidence and publication history.":
    "Xem bằng chứng hiệu quả hiện có và lịch sử xuất bản.",
  "Review before applying": "Xem trước khi áp dụng",
  "Review client reports, set priority, and move work through the product queue.":
    "Xem báo cáo khách, đặt ưu tiên và đưa việc qua hàng chờ sản phẩm.",
  "Review each account’s status and reconnect when requested. Available platforms and account limits are shown in the interface.":
    "Xem trạng thái mỗi tài khoản và kết nối lại khi được yêu cầu. Nền tảng và giới hạn tài khoản hiện trong giao diện.",
  "Review or export one of your open edits before starting another. Open edits: {{count}}":
    "Xem hoặc xuất một bản dựng đang mở trước khi tạo bản khác. Bản dựng mở: {{count}}",
  "Review recent studio activity and choose the next useful action.":
    "Xem hoạt động studio gần đây và chọn tác vụ hữu ích tiếp theo.",
  "Review the account terms": "Xem điều khoản tài khoản",
  "Review the credit cost before starting. Check the job status and the finished clip before using it; a generated file can be reused from Library.":
    "Xem chi phí tín dụng trước khi bắt đầu. Kiểm tra trạng thái việc và clip hoàn tất trước khi dùng; tệp được tạo dùng lại từ Thư viện được.",
  "Review the current value and update it with real results. Edit a goal when its scope changes rather than leaving an outdated target.":
    "Xem giá trị hiện tại và cập nhật bằng kết quả thực. Sửa mục tiêu khi phạm vi đổi thay vì giữ đích lỗi thời.",
  "Review the generated hook, body, and ending. Check factual claims, then save the script or continue refining it.":
    "Xem lại phần mở đầu thu hút, nội dung và kết thúc đã tạo. Kiểm tra các khẳng định thực tế, rồi lưu kịch bản hoặc tiếp tục tinh chỉnh.",
  "Review the next action": "Xem lại hành động tiếp theo",
  "Review the product’s content rules and practical review steps.":
    "Xem các quy tắc nội dung và các bước kiểm tra thực tế của sản phẩm.",
  "Review the relevant sections and the date shown on this page. Follow linked documents when you need the full context.":
    "Xem các mục liên quan và ngày hiển thị trên trang này. Mở các tài liệu được liên kết khi bạn cần đầy đủ ngữ cảnh.",
  "Review the reported match method and available record. Recorded origin, an embedded mark, and a verified file match provide different evidence.":
    "Xem phương thức đối chiếu được báo cáo và bản ghi hiện có. Nguồn gốc được ghi nhận, dấu nhúng và kết quả đối chiếu tệp đã xác minh cung cấp các loại bằng chứng khác nhau.",
  "Review the systems": "Xem lại các hệ thống",
  "Review the terms that apply to your account and use of the service.":
    "Xem các điều khoản áp dụng cho tài khoản và việc sử dụng dịch vụ của bạn.",
  "Review the whole edit before export. Your current device renders the video: keep the page open, and try 720p or a shorter edit if memory is limited. Download-only avoids a Library upload; Library saving makes the result available for later publication. AI media needs Library saving to finalize its source marking. Rendering uses no AI credits. AI generation, hosting and storage still have costs and allowances.":
    "Xem lại toàn bộ bản dựng trước khi xuất. Thiết bị hiện tại của bạn kết xuất video: hãy giữ trang mở và thử 720p hoặc bản dựng ngắn hơn nếu bộ nhớ hạn chế. Chỉ tải xuống sẽ bỏ qua bước tải lên Thư viện; lưu vào Thư viện giúp kết quả có thể dùng để xuất bản sau này. Nội dung AI cần được lưu vào Thư viện để hoàn tất dấu nguồn gốc. Kết xuất không dùng tín dụng AI. Việc tạo bằng AI, lưu trữ trên máy chủ và lưu trữ dữ liệu vẫn có chi phí và hạn mức.",
  "Review tracked path ·": "Xem đường dẫn được theo dõi ·",
  "Review your plan, available credits, usage, and checkout options.":
    "Xem gói, tín dụng hiện có, mức sử dụng và các lựa chọn thanh toán.",
  "Reviewable decisions": "Các quyết định có thể xem xét",
