  "Reviews a supplied video for editorial hook, pacing, and time-based suggestions. Scores are rubric assessments, not predicted views.":
    "Đánh giá video được cung cấp về phần mở đầu thu hút, nhịp độ và các đề xuất theo thời gian. Điểm là đánh giá theo tiêu chí, không phải dự đoán lượt xem.",
