    "Dùng PNG hoặc WebP trong suốt cho logo không nền.",
  "Use an available sign-in provider or complete the name, email, and password fields. Use an email address you can access.":
    "Dùng nhà cung cấp đăng nhập khả dụng hoặc điền tên, email và mật khẩu. Dùng địa chỉ email bạn có thể truy cập.",
  "Use as starting point": "Dùng làm điểm khởi đầu",
  "Use at least 8 characters. Your new password replaces the old one immediately.":
    "Dùng ít nhất 8 ký tự. Mật khẩu mới thay thế mật khẩu cũ ngay lập tức.",
