  "Warm morning light, tactile and calm":
    "Ánh sáng ban mai ấm áp, giàu cảm giác chất liệu và yên tĩnh",
  "Warm paper surfaces and high-contrast controls.":
    "Bề mặt giấy ấm áp và điều khiển tương phản cao.",
  "Waveform unavailable": "Dạng sóng không khả dụng",
  "We may change or suspend features for security, law, maintenance, or provider changes. We do not promise marketing results, virality, or uninterrupted availability. Nothing excludes liability that law does not allow us to exclude or mandatory consumer remedies. Otherwise, total liability relating to the service is limited to the amount paid in the 12 months before the event.":
    "Chúng tôi có thể thay đổi hoặc tạm ngưng tính năng vì bảo mật, pháp luật, bảo trì hoặc thay đổi nhà cung cấp. Chúng tôi không hứa hẹn kết quả tiếp thị, tính lan truyền hay khả năng hoạt động không gián đoạn. Không điều gì loại trừ trách nhiệm mà pháp luật không cho phép loại trừ hoặc các biện pháp khắc phục bắt buộc dành cho người tiêu dùng. Trong các trường hợp khác, tổng trách nhiệm liên quan đến dịch vụ giới hạn ở số tiền đã thanh toán trong 12 tháng trước sự kiện.",
  "We may suspend an account for violations, security risk, non-payment, or legal duties, using proportionate measures. Italian law applies without depriving consumers of mandatory protections in their country of residence or mandatory courts. For support or complaints: ":
    "Chúng tôi có thể tạm ngưng tài khoản do vi phạm, rủi ro bảo mật, không thanh toán hoặc nghĩa vụ pháp lý, bằng biện pháp tương xứng. Luật Ý áp dụng mà không tước bỏ các quyền bảo vệ bắt buộc của người tiêu dùng tại nước cư trú hoặc thẩm quyền tòa án bắt buộc. Để được hỗ trợ hoặc khiếu nại: ",
  "We sent a secure confirmation link to":
    "Chúng tôi đã gửi liên kết xác nhận an toàn tới",
  "We'll send you a reset link": "Chúng tôi sẽ gửi cho bạn liên kết đặt lại",
