  "When reporting an issue, include the failing action and its error alongside the relevant status. Review the AI information available here when learning how the tools behave.":
    "Khi báo cáo vấn đề, nêu thao tác thất bại và lỗi cùng trạng thái liên quan. Xem thông tin AI có ở đây khi tìm hiểu cách các công cụ hoạt động.",
  "Where applicable, you may request access, correction, deletion, restriction, portability, or objection; withdraw consent without affecting prior processing; and complain to the Italian Data Protection Authority or another competent authority. Account settings include data export and a deletion-request path.":
    "Khi áp dụng, bạn có thể yêu cầu truy cập, sửa, xóa, hạn chế, chuyển dữ liệu hoặc phản đối; rút lại sự đồng ý mà không ảnh hưởng việc xử lý trước đó; và khiếu nại với Cơ quan Bảo vệ Dữ liệu Ý hoặc cơ quan có thẩm quyền khác. Thiết lập tài khoản có chức năng xuất dữ liệu và lộ trình yêu cầu xóa.",
